INSERT INTO `documentos` VALUES
(1,NULL,'bienvenida',NULL,NULL,NULL,NULL,'[PARRAFO]\r\nBIENVENIDOS\r\na esta su liga\r\n[/PARRAFO]'),
(2,NULL,'consejo_CIF',NULL,NULL,NULL,NULL,'Ponga un texto aqui'),
(3,'2012-06-07','AR324F','Reglas',6,6,NULL,'El torneo se jugará en formato <i>Round Robin</i> entre todos los equipos en 2 rondas, dejando a cada equipo un total de 5 partidos de local y 5 de visitante. \n\n<p>El primer sembrado asciende directamente a la primera división, mientras que el segundo se medirá en 2 partidos al penúltimo lugar de la primera div.');
